definition.script:
import groovy.json.JsonSlurper;

def infrastructure_git_hash

pipeline {
  agent any

  options {
    skipDefaultCheckout(true)
  }

  stages {
    stage('Clean Workspace') {
      steps {
        deleteDir()
      }
    }

    stage('Resolve Infrastructure Git Hash') {
      steps {
        script {
          if (params.INFRASTRUCTURE_GIT_HASH?.trim()) {
            infrastructure_git_hash = params.INFRASTRUCTURE_GIT_HASH.trim()
            echo "Using provided INFRASTRUCTURE_GIT_HASH: ${infrastructure_git_hash}"
          } else {
            def result = build job: 'Retrieve Build Spec'
            copyArtifacts filter: 'build-spec.json', projectName: 'Retrieve Build Spec', selector: specific("" + result.number)
            def buildSpec = new JsonSlurper().parse(new File("${env.WORKSPACE}/build-spec.json"))
            infrastructure_git_hash = buildSpec.infrastructure_git_hash
            echo "Resolved INFRASTRUCTURE_GIT_HASH from release control: ${infrastructure_git_hash}"
          }
        }
      }
    }

    stage('Checkout Infrastructure Repo') {
      steps {
        checkout([
          $class: 'GitSCM',
          userRemoteConfigs: [[
            url: "${infrastructure_git_repo}",
            credentialsId: "${git_credentials_id}"
          ]],
          branches: [[name: infrastructure_git_hash]]
        ])
      }
    }

    stage('Download Template') {
      steps {
        sh '''#!/bin/bash
set -euo pipefail

source_scripts_folder="${JENKINS_HOME}/workspace/Bash_Functions/"
shopt -s nullglob
for script_file in "$source_scripts_folder"*.sh; do
    chmod +x "$script_file"
    if [[ -f "$script_file" && -x "$script_file" ]]; then
        source "$script_file"
    fi
done
shopt -u nullglob

for fn in assume_role reset_role; do
    if ! command -v "$fn" >/dev/null 2>&1; then
        echo "Error: required function '$fn' was not loaded from $source_scripts_folder." >&2
        exit 1
    fi
done

: "${SERVICE:?SERVICE is required}"
: "${stack_s3_bucket:?stack_s3_bucket is required}"

case "$SERVICE" in
    Gateway)
        template_file="gateway.env.tftpl"
        template_prefix="configs/gateway/templates"
        ;;
    Operations)
        template_file="operations.env.tftpl"
        template_prefix="configs/operations/templates"
        ;;
    Query)
        template_file="query.env.tftpl"
        template_prefix="configs/query/templates"
        ;;
    "HPDS Auth")
        template_file="hpds-auth.env.tftpl"
        template_prefix="configs/hpds/templates"
        ;;
    "HPDS Open")
        template_file="hpds-open.env.tftpl"
        template_prefix="configs/hpds/templates"
        ;;
    Visualization)
        template_file="visualization.env.tftpl"
        template_prefix="configs/pic-sure-visualization/templates"
        ;;
    *)
        echo "Error: unsupported SERVICE selection." >&2
        exit 1
        ;;
esac

repo_template="app-infrastructure/template-renderer/templates/$template_file"
TARGET_STACK="${TARGET_STACK:-}"
role_assumed=false
cleanup() {
    if [[ "$role_assumed" == true ]]; then
        reset_role
    fi
}
trap cleanup EXIT

assume_role
role_assumed=true

found=false
if [[ -n "$TARGET_STACK" ]] && aws s3 --sse=AES256 cp "s3://$stack_s3_bucket/$template_prefix/$TARGET_STACK/$template_file" "$template_file" >/dev/null 2>&1; then
    echo "Using stack-specific S3 template for $template_file"
    found=true
fi

if [[ "$found" == false ]] && aws s3 --sse=AES256 cp "s3://$stack_s3_bucket/$template_prefix/$template_file" "$template_file" >/dev/null 2>&1; then
    echo "Using shared S3 template for $template_file"
    found=true
fi

if [[ "$found" == false ]]; then
    echo "No S3 template found, using repo version of $template_file"
    cp "$repo_template" "$template_file"
fi
'''
      }
    }
  }

  post {
    success {
      archiveArtifacts artifacts: '*.env.tftpl', allowEmptyArchive: false
    }
  }
}
